/**
 * Canonical HTTP response payload emitted by http.* nodes.
 *
 * Downstream routing branches on ``status`` (e.g. ``inputs['status'] < 300``
 * on a conditional edge). Transport-level failures never produce this shape
 * — they are node Failures (``code='http_transport_error'``).
 *  *
 *  * Kind `http_response` (registry v8).
 */
export interface HttpResponse {
  /**
   * The final URL the request resolved to, after any redirects.
   */
  url: string;
  /**
   * Parsed JSON when the content-type is JSON-like; the decoded text otherwise. Use this for structured downstream steps.
   */
  body?: JsonValue;
  /**
   * Raw response body as text, truncated to the max_bytes cap.
   */
  text?: string;
  /**
   * The registered kind this payload is an instance of.
   */
  __kind?: "http_response";
  /**
   * HTTP status code (e.g. 200, 404).
   */
  status: number;
  /**
   * Response headers, with lower-cased keys.
   */
  headers?: Record<string, string>;
  /**
   * Wall-clock time for the request, in milliseconds.
   */
  elapsed_ms?: number;
  /**
   * The response's Content-Type header value.
   */
  content_type?: string;
}

/**
 * On normal (resumed) execution, the value the user supplied becomes this
 * node's output. On resume, the scheduler populates this model from the
 * resume payload.
 *  *
 *  * Kind `human_answer` (registry v8).
 */
export interface HumanAnswer {
  /**
   * The registered kind this payload is an instance of.
   */
  __kind?: "human_answer";
  /**
   * The value the person supplied when the run resumed.
   */
  answer?: JsonValue;
  /**
   * Anything else the UI collected alongside the answer. Declared so client-authored keys have a readable home — at the root nothing could know to look for them.
   */
  extras?: {
    /**
     * The registered kind this payload is an instance of, when it is one.
     */
    __kind?: string;
    [key: string]: JsonValue | string | undefined;
  };
  /**
   * WHO decided — the person who was asked, or the fallback that decided for them once the deadline passed. Stamped by the engine on resume; never author-supplied, never client-supplied. Travels downstream with the answer so any surface can show a user that an agent decided because nobody answered in time.
   */
  matrx_decision?: DecisionProvenance | null;
}

