/**
 * Kind `meet.meeting_prep.offer` (registry v4).
 */
export interface MeetMeetingPrepOffer {
  /**
   * The registered kind this payload is an instance of.
   */
  __kind?: "meet.meeting_prep.offer";
  /**
   * One line per invited person: name, email when known, whether they are inside the organization or an outside guest, their role (guest or co-host) and their answer (going / not going / maybe / no answer). 'No guests invited yet.' when empty.
   */
  guests: string;
  /**
   * Who is running the meeting (the reader of the brief).
   */
  host_name: string;
  /**
   * For outside guests only: the CRM contact each email matched, their company, and the most recent logged activities (date, channel, subject). 'No outside guests.' or 'No CRM contact matched.' when there is nothing — then say nothing about them beyond their name.
   */
  crm_context: string;
  /**
   * When it happens, in the meeting's own time zone, with its length and repeat rule in words — or 'Not scheduled yet'.
   */
  meeting_when: string;
  /**
   * The meeting's title as the host wrote it — a label, never evidence.
   */
  meeting_title: string;
  /**
   * The agenda the host already wrote, verbatim, or 'No agenda yet.' Build on it; never contradict it.
   */
  meeting_agenda: string;
  /**
   * What the last meeting of this series produced: its date, summary and decisions. 'No earlier meeting in this series.' when there is none.
   */
  previous_meeting: string;
  /**
   * Action items from earlier meetings of this series that are NOT done, each with its owner and task status. 'No open action items.' when everything is done or nothing was assigned.
   */
  open_action_items: string;
}

/**
 * Kind `meet.meeting_record.offer` (registry v12).
 */
export interface MeetMeetingRecordOffer {
  /**
   * The registered kind this payload is an instance of.
   */
  __kind?: "meet.meeting_record.offer";
  /**
   * How many notes, decisions and action items have already been recorded for this meeting.
   */
  note_count: number;
  /**
   * One line per participant: display name, role, and whether they have spoken. This is the roster a person would read before writing minutes.
   */
  participants: string;
  /**
   * 0-based index of this live-notes window. Absent outside a windowed pass.
   */
  window_index?: number;
  /**
   * The meeting's title as the host set it. Use it to know what the conversation is supposed to be about; it is a label, never evidence.
   */
  meeting_title: string;
  /**
   * ISO-8601 UTC end of this window (exclusive).
   */
  window_end_at?: string;
  /**
   * Every live note already written for this meeting, oldest first, each with its window. Absent when nothing has been written yet.
   */
  existing_notes?: string;
  /**
   * Whether the meeting is 'live' (still running) or 'ended' (finished). While it is live, the transcript is necessarily incomplete, so it should be described as a work in progress rather than a finished record.
   */
  meeting_status: string;
  /**
   * The names of everyone who actually spoke, based on what was captured. A quote or decision should only ever be attributed to someone on this list.
   */
  speaker_roster: string[];
  /**
   * How many seconds of real time this window covers.
   */
  window_seconds?: number;
  /**
   * The meeting's recording row state ('recording', 'processing', 'available', 'failed'). Absent when the meeting was never recorded. A holder can tell a person whether a recording exists to go back to.
   */
  recording_state?: string;
  /**
   * The full transcript of the meeting so far, in order, as lines like "[mm:ss] Speaker: what they said." It may be shortened to a maximum length; when that happens the oldest part is cut and a separate flag notes that it was shortened.
   */
  transcript_full: string;
  /**
   * ISO-8601 UTC start of this window (inclusive).
   */
  window_start_at?: string;
  /**
   * When the meeting ended, ISO-8601 UTC. Absent while it is live.
   */
  meeting_ended_at?: string;
  /**
   * What the automatic note-taker is currently doing for this meeting, such as 'transcribing'. Not present if a note-taker has never run — which is also why there would be no transcript yet.
   */
  note_taker_state?: string;
  /**
   * How many people (agents included) the roster holds.
   */
  participant_count: number;
  /**
   * The most recent part of the transcript, useful for answering a question about what was just said.
   */
  transcript_recent: string;
  /**
   * Only the part of the transcript that falls inside this particular time window. Not present outside a live-notes run.
   */
  transcript_window?: string;
  /**
   * Not present on a first attempt. Present only when the previous attempt's answer was rejected as unusable, in which case this explains exactly what was wrong and what to do instead. Fix only that, and change nothing else.
   */
  writer_correction?: string;
  /**
   * Decisions already recorded for this meeting. A holder that reads these never re-reports a settled decision as new.
   */
  existing_decisions?: string[];
  /**
   * When the meeting started, ISO-8601 UTC. Absent for a meeting that has a row but was never joined — timestamps then count from the first spoken segment instead.
   */
  meeting_started_at?: string;
  /**
   * How many final segments each speaker produced, in the slice handed over. Lets a holder notice that the person a decision is attributed to barely spoke.
   */
  speaker_turn_counts?: string;
  /**
   * The live note written for the window before this one, so the next note can continue the record instead of repeating it. Not present for the first window.
   */
  previous_window_note?: string;
  /**
   * True when the character budget dropped the oldest text. A truncated transcript cannot support a claim about the start of the meeting.
   */
  transcript_truncated: boolean;
  /**
   * Final segments whose start time falls inside this window.
   */
  window_segment_count?: number;
  /**
   * Action items already recorded for this meeting, each with who it was assigned to.
   */
  existing_action_items?: string;
  /**
   * Characters of transcript as offered, after any truncation.
   */
  transcript_char_count: number;
  /**
   * The maximum transcript length, in characters, allowed for this organization.
   */
  transcript_char_budget: number;
  /**
   * How many whole minutes people have actually been talking, measured from the first thing said to the last. This is not the same as how long the meeting room has been open.
   */
  meeting_elapsed_minutes: number;
  /**
   * How many final segments are in the text that was handed over.
   */
  transcript_segment_count: number;
  /**
   * How many spoken segments the whole meeting has recorded so far, for comparing against how much of the transcript was actually given.
   */
  transcript_total_segment_count: number;
}

