/**
 * Kind `ner.document_orientation.offer` (registry v10).
 */
export interface NerDocumentOrientationOffer {
  /**
   * The registered kind this payload is an instance of.
   */
  __kind?: "ner.document_orientation.offer";
  /**
   * The person whose document is being ingested.
   */
  user_id?: string;
  /**
   * The scope this call is about, when the call is for one scope.
   */
  scope_id?: string;
  /**
   * The ID of the ingested document this call is about.
   */
  source_id?: string;
  /**
   * What kind of record the ingested document is (for example a file or a note).
   */
  source_kind?: string;
  /**
   * Ranked extracted-entity frequency records for the document.
   */
  top_entities: unknown;
  /**
   * The ID of this ingest pass; every call in one pass shares it.
   */
  ingest_run_id?: string;
  /**
   * The document's display label.
   */
  document_label: string;
  /**
   * The organization the ingest runs for, when there is one.
   */
  organization_id?: string;
  /**
   * The user's current scope tree (types, scopes, names).
   */
  user_scope_tree: unknown;
  /**
   * How many scopes the person's scope tree holds.
   */
  user_scope_count?: number;
  /**
   * Top entity co-occurrence records for the document.
   */
  top_cooccurrences: unknown;
  /**
   * How many chunks the document was split into.
   */
  total_chunk_count?: number;
  /**
   * Human-readable size hint (pages/words).
   */
  document_size_hint: string;
  /**
   * How many distinct entities the document yielded after consolidation.
   */
  total_entity_count?: number;
  /**
   * A bounded sample of the document's text.
   */
  document_text_sample: string;
}

