/**
 * Kind `orchestration.tool_failure_standoff.offer` (registry v7).
 */
export interface OrchestrationToolFailureStandoffOffer {
  /**
   * The registered kind this payload is an instance of.
   */
  __kind?: "orchestration.tool_failure_standoff.offer";
  /**
   * The model driving the run. The guard exists for small models; a verdict may legitimately weigh a capable model's self-correction differently.
   */
  model_id: string;
  /**
   * The mandate goal or system instruction of the run in progress, so 'is this tool still needed at all' is answerable.
   */
  run_goal?: string;
  /**
   * The tool whose failures tripped the guard, e.g. 'dataset'.
   */
  tool_name: string;
  /**
   * The full set of rules for what a legal call to this tool looks like, so a decision can say whether the arguments were ever valid.
   */
  tool_schema?: unknown;
  /**
   * Size of that rolling window (20 today).
   */
  window_size: number;
  /**
   * The category of each recent failure, in order — the only set of categories a decision is allowed to name.
   */
  error_classes: string[];
  /**
   * The maximum number of failures allowed for this run before the guard steps in, so a decision can weigh how far past it things are.
   */
  failure_limit: number;
  /**
   * True when this runs as a workflow step with nobody to answer a pause. Pausing an unattended run is a failure, not a wait — the same verdict has different costs on the two sides of this flag.
   */
  is_unattended: boolean;
  /**
   * The error message shown for each recent failure, shortened. Often not available — a job that needs it must say so rather than guess.
   */
  error_messages?: string[];
  /**
   * Failures across all tools for the whole run — the un-windowed denominator.
   */
  failures_total: number;
  /**
   * Every tool call in the run so far, successful or not.
   */
  call_count_total: number;
  /**
   * The tool's own agent-facing description, verbatim — what the model was told the tool does.
   */
  tool_description?: string;
  /**
   * The most recent calls to this tool in this run, in full detail — what was tried, when, and whether it succeeded — so it can be judged whether the arguments actually changed between attempts.
   */
  recent_calls_json: unknown;
  /**
   * The same recent calls condensed to one short line per call, oldest first, so a repeat is easy to spot at a glance.
   */
  recent_calls_text: string;
  /**
   * Whether the guard has already disabled tools once in this run.
   */
  already_intervened: boolean;
  /**
   * Failures across all tools in the guard's rolling window.
   */
  failures_in_window: number;
  /**
   * Failed calls of this specific tool so far in this run.
   */
  failures_this_tool: number;
  /**
   * Successful calls of this tool in this run — a tool that worked then broke is an outage shape.
   */
  successes_this_tool: number;
  /**
   * Names of the other tools still enabled on this request — whether there is another route to the same goal.
   */
  other_tools_available?: string[];
  /**
   * One stable identifier per recent call of this tool, in order. Two equal adjacent entries are a byte-identical repeat — the deterministic fact behind the 'near-identical repeats' question, so the model confirms rather than eyeballs it.
   */
  arguments_fingerprints: string[];
  /**
   * The model's own reasoning or assistant text emitted between the recent calls, in order, condensed. This is what distinguishes 'I'll try a different ID format instead' from silence.
   */
  assistant_text_between_calls?: string;
  /**
   * Failed calls of this tool since its last success (0 if it just succeeded).
   */
  consecutive_failures_this_tool: number;
}

