/**
 * Kind `research.source_read_candidate.offer` (registry v5).
 */
export interface ResearchSourceReadCandidateOffer {
  /**
   * The source URL, verbatim.
   */
  url: string;
  /**
   * The search position this source was returned at. Deliberately withheld from the authority judgement itself, because a judge shown the rank launders the search engine's ordering back in as an independent opinion.
   */
  rank?: number;
  /**
   * The listing title, verbatim.
   */
  title: string;
  /**
   * The registered kind this payload is an instance of.
   */
  __kind?: "research.source_read_candidate.offer";
  /**
   * The registrable host (e.g. nih.gov), for domain-led judgement.
   */
  hostname: string;
  /**
   * The publish/updated date the search provider reported. Present for 69% of sources (10,772 of 15,527). Absent means UNKNOWN — never infer it from the URL or the snippet.
   */
  page_age?: string;
  /**
   * The research.rs_source id.
   */
  source_id: string;
  /**
   * How many candidate sources this topic holds. Median 259, max 1,681 measured — a 'top source' means something different at 12 and at 1,681.
   */
  batch_size: number;
  /**
   * The research topic's name, verbatim as the user wrote it.
   */
  topic_name: string;
  /**
   * The search-result snippet, verbatim. Present for 97% of sources; for 92.5% it is the ONLY content signal that will ever exist.
   */
  description?: string;
  /**
   * The kind of source this is: a web page, a video, a PDF, or something else. A video and a page are not commensurable and must not be scored on one axis.
   */
  source_type: string;
  /**
   * The first 3,000 characters of the fetched page text, when a capture succeeded. Present for 7.5% of sources (1,170 of 15,527).
   */
  content_head?: string;
  /**
   * The FULL fetched page text (avg 24,337 chars on successful captures). Absent for 92.5% of sources; a job needing it must say so and refuse honestly rather than judge from the snippet while claiming otherwise.
   */
  content_text?: string;
  /**
   * What this specific keyword is meant to find, when the user set one.
   */
  keyword_goal?: string;
  /**
   * The keyword/query this source was returned for.
   */
  search_query?: string;
  /**
   * Hostnames of the batch's other candidates, deduped — the cheap shape of sibling_titles for a decision model with a small state budget.
   */
  sibling_sites?: string[];
  /**
   * description + extra_snippets joined into one bounded block, for a decision model that takes a single text field.
   */
  snippet_block?: string;
  /**
   * Additional provider snippets (avg ~3.6 entries), only captured for results at or above search position 50. Present for 74% of sources.
   */
  extra_snippets?: string[];
  /**
   * The score that decides reading order today. Offered so a candidate agent can disagree with it explicitly, never so it can simply copy it.
   */
  pre_read_score?: number;
  /**
   * Titles of up to 50 other candidates in the same batch, so authority and redundancy can be judged RELATIVELY instead of by domain reputation alone.
   */
  sibling_titles?: string[];
  /**
   * The batch ranker's 0-100 domain-led authority prior. Present on 90% of sources. A prior from a different question, not this answer.
   */
  authority_score?: number;
  /**
   * The first 600 characters of the fetched text, for budget-bound decisions.
   */
  content_excerpt?: string;
  /**
   * The near-duplicate cluster the prior batch triage assigned (syndicated release, per-city landing page). Present on 13% of sources.
   */
  redundancy_group?: string;
  /**
   * The topic's composed intent brief — the actual question being researched. Declared on 2 of 53 topics today; absent means the topic name and description ARE the question.
   */
  research_question?: string;
  /**
   * The batch ranker's 0-100 'will fetching this yield article text'. Present on 72% of sources. Null means NOT ASSESSED, never zero.
   */
  scrape_worthiness?: number;
  /**
   * The topic's description, verbatim. Present on 87% of topics.
   */
  topic_description?: string;
  /**
   * Length of the fetched text, 0 when the capture failed. A capture row exists for every failed fetch with length 0 — presence of a row is NOT presence of text.
   */
  content_char_count?: number;
  /**
   * How recent this topic needs its evidence to be. When the topic never declared a need, this falls back to the platform's default and is not a real statement of need — a currency judgement made against an undeclared need must answer unknown.
   */
  topic_freshness_weight?: string;
}

