/**
 * Kind `scraper.page_capture.offer` (registry v5).
 */
export interface ScraperPageCaptureOffer {
  /**
   * rs_source.hostname — the domain, for hosts with known behaviour.
   */
  host: string;
  /**
   * The full extracted text. Absent for 3,590 of 4,784 current rows. A decision model with a 32k-token state must prefer text_head.
   */
  text?: string;
  /**
   * The registered kind this payload is an instance of.
   */
  __kind?: "scraper.page_capture.offer";
  /**
   * The URL the server actually answered from, after redirects (FetchResult.response_url). Differs from requested_url on the decoy-profile and consent-interstitial failure modes. In memory at the call site only — rs_content has no column for it.
   */
  final_url?: string;
  /**
   * The research.rs_source id being scraped.
   */
  source_id: string;
  /**
   * The first 6,000 characters of the extracted text. Every wall, block, consent overlay and 404 announces itself inside this window; a long article does not need more of itself to be recognised as one.
   */
  text_head?: string;
  /**
   * The served page's <title>, verbatim. Challenge pages announce themselves here.
   */
  page_title?: string;
  /**
   * rs_topic.name — the research subject. Present for 4,784 of 4,784 rows.
   */
  topic_name: string;
  /**
   * Final HTTP status code (FetchResult.status_code). Not persisted anywhere.
   */
  http_status?: number;
  /**
   * The kind of content that came back: a web page, a PDF, an image, or structured data.
   */
  content_type: string;
  /**
   * The URL we asked for, verbatim.
   */
  requested_url: string;
  /**
   * How the page was captured: a plain fetch, a full browser, the browser extension, or skipped by policy.
   */
  capture_method: string;
  /**
   * The caller's dimensions for this page — e.g. ['services', 'employees', 'pricing']. NOT stored anywhere today: research.rs_tag holds 24 rows of tags assigned AFTER reading, which is a different thing. The caller supplies these, and they are the ONLY legal keys in the dimensions answer.
   */
  dimension_tags?: string[];
  /**
   * Each hop as 'status url', in order, when the fetch recorded one.
   */
  redirect_chain?: string[];
  /**
   * The keyword whose search produced this URL, via platform.associations research_source -> research_keyword. Exists for 4,756 of 4,770 scraped sources (99.7%) and is NOT passed into scrape_source today.
   */
  search_keyword?: string;
  /**
   * Length of the raw HTML. Large HTML with tiny text is the SPA-shell signature.
   */
  html_char_count?: number;
  /**
   * Length of the extracted text. Offered because it is cheap and a consumer may want it — NEVER as the verdict. Measured: it passes 1,083 of the 1,194 rows that have any text at all.
   */
  text_char_count: number;
  /**
   * rs_topic.intent_brief — the composed statement of what this research is FOR. Present for 2 of 49 topics (132 of 4,784 rows). Its absence is what makes the intent question refusable, never guessable.
   */
  topic_intent_brief?: string;
  /**
   * rs_source.server_attempts — how many times we have already tried this URL.
   */
  prior_attempt_count?: number;
  /**
   * The title the SEARCH ENGINE gave this URL (rs_source.title, present on 15,526 of 15,527 rows). Disagreement with page_title is itself evidence.
   */
  search_result_title?: string;
  /**
   * Number of links parsed out. A rendered article has them; a consent gate does not.
   */
  extracted_link_count?: number;
  /**
   * rs_source.last_server_failure_reason. Measured distribution over 4,784 current rows: proxy_error 3,342, bad_status 152, request_error 21, cloudflare_block 20, low_text_content 18.
   */
  prior_failure_reason?: string;
  /**
   * Optional 'tag — one-line definition' entries, one per dimension, so a dimension means the same thing to every agent bound to this mandate. Absent, a tag is judged on its name alone.
   */
  dimension_definitions?: string[];
  /**
   * One line describing any configured policy for this host, such as which part of the page to read, a minimum length, or a forced capture method.
   */
  domain_policy_summary?: string;
  /**
   * Number of images parsed out.
   */
  extracted_image_count?: number;
  /**
   * rs_source.description — the snippet that made this URL worth fetching.
   */
  search_result_snippet?: string;
  /**
   * Char counts of earlier versions of this source's content, newest first (5,498 rows exist against 4,784 current ones). A render that produced less than the previous attempt is a downgrade, not a rescue.
   */
  prior_capture_char_counts?: string[];
}

